<?php $title = 'Manage courts'; ?>
<section class="mx-auto max-w-6xl px-5 py-12"><div class="mb-8 flex flex-wrap items-center justify-between gap-4"><div><p class="eyebrow">FACILITY MANAGEMENT</p><h1 class="mt-2 font-display text-4xl font-extrabold">Your courts.</h1><p class="mt-2 text-sm text-slate-500">Manage rates, photos, operating hours, and maintenance.</p></div><a class="primary-button !mt-0" href="<?= h(url('admin.court.form')) ?>">Add a court +</a></div>
<div class="grid gap-5"><?php foreach ($courts as $court): ?><article class="grid gap-5 border border-stone-200 bg-white p-5 lg:grid-cols-[180px_1fr]"><img src="<?= h(court_photo_url($court)) ?>" alt="<?= h($court['name']) ?>" class="h-36 w-full rounded object-cover lg:w-44"><div><div class="flex flex-wrap items-start justify-between gap-4"><div><p class="eyebrow"><?= h($court['sport']) ?> · ₱<?= number_format((float)$court['hourly_rate'],0) ?>/HR</p><h2 class="mt-1 font-display text-xl font-bold"><?= h($court['name']) ?></h2><p class="mt-1 text-sm text-slate-500"><?= h($court['description']) ?></p><p class="mt-2 text-xs text-slate-500"><?= h($court['opens_at']) ?> — <?= h($court['closes_at']) ?> · <?= (int)$court['is_active']?'Active':'Inactive' ?></p></div><div class="flex gap-3"><a class="text-xs underline" href="<?= h(url('admin.court.form',['id'=>$court['id']])) ?>">Edit</a><?php if ((int)$court['is_active']): ?><form method="post" action="<?= h(url('admin.court.deactivate')) ?>" onsubmit="return confirm('Deactivate this court?')"><?= csrf_field() ?><input type="hidden" name="court_id" value="<?= (int)$court['id'] ?>"><button class="text-xs text-rose-700 underline">Deactivate</button></form><?php endif; ?></div></div>
<form class="maintenance-form mt-4 flex flex-wrap items-end gap-2 border-t border-stone-100 pt-4" method="post" action="<?= h(url('admin.maintenance.add')) ?>"><?= csrf_field() ?><input type="hidden" name="court_id" value="<?= (int)$court['id'] ?>"><label class="field-label">From<input class="control" type="datetime-local" name="start_at" required></label><label class="field-label">Until<input class="control" type="datetime-local" name="end_at" required></label><label class="field-label min-w-48 flex-1">Reason<input class="control" name="reason" maxlength="180" placeholder="Maintenance reason" required></label><button class="rounded bg-slate-900 px-4 py-3 text-xs font-bold text-white">Block time</button></form>
<?php $q=db()->prepare('SELECT * FROM maintenance_blocks WHERE court_id=? ORDER BY start_at'); $q->execute([$court['id']]); $blocks=$q->fetchAll(); ?><?php if ($blocks): ?><div class="mt-3"><p class="eyebrow">MAINTENANCE BLOCKS</p><?php foreach ($blocks as $block): ?><div class="flex flex-wrap justify-between gap-2 border-t border-stone-100 py-2 text-xs"><span><?= h(format_datetime($block['start_at'])) ?> – <?= h(format_datetime($block['end_at'],'g:i A')) ?> · <?= h($block['reason']) ?></span><form method="post" action="<?= h(url('admin.maintenance.delete')) ?>"><?= csrf_field() ?><input type="hidden" name="block_id" value="<?= (int)$block['id'] ?>"><button class="text-rose-700 underline">Remove</button></form></div><?php endforeach; ?></div><?php endif; ?></div></article><?php endforeach; ?></div></section>
